        if (paMapper != null) {
            Map map = paMapper.getUser(assertions, srcID, target);
            name = (String) map.get(PartnerAccountMapper.NAME);
            org =  (String) map.get(PartnerAccountMapper.ORG);
            attrMap = (Map) map.get(PartnerAccountMapper.ATTRIBUTE);
        }

        if (attrMap == null) {
