@Override
    @Nullable
    public MongoDbSession load(String sessionId) {
        DBObject query = new BasicDBObject();
        query.put(MongoDbSession.FIELD_SESSION_ID, sessionId);

        DBObject result = findOne(MongoDbSession.class, query);
        if (result == null) {
            return null;
        }
        final Object objectId = result.get("_id");
        return new MongoDbSession((ObjectId) objectId, result.toMap());
    }

@Override
    public <T extends Persisted> int destroy(T model) {
        int affectedDocs = super.destroy(model);
        if (affectedDocs != 0 && model instanceof MongoDbSession session) {
            eventBus.post(new SessionDeletedEvent(session.getSessionId()));
        }
        return affectedDocs;
    }

@Override
    public Collection<MongoDbSession> loadAll() {
        DBObject query = new BasicDBObject();
        List<MongoDbSession> dbSessions = Lists.newArrayList();
        final List<DBObject> sessions = query(MongoDbSession.class, query);
        for (DBObject session : sessions) {
            dbSessions.add(new MongoDbSession((ObjectId) session.get("_id"), session.toMap()));
        }

        return dbSessions;
    }

@Override
    public SimpleSession daoToSimpleSession(MongoDbSession sessionDAO) {
        final SimpleSession session = new SimpleSession();
        session.setId(sessionDAO.getSessionId());
        session.setHost(sessionDAO.getHost());
        session.setTimeout(sessionDAO.getTimeout());
        session.setStartTimestamp(sessionDAO.getStartTimestamp());
        session.setLastAccessTime(sessionDAO.getLastAccessTime());
        session.setExpired(sessionDAO.isExpired());
        session.setAttributes(sessionDAO.getAttributes());
        return session;
    }

@Override
    protected void doDelete(Session session) {
        LOG.debug("Deleting session");
        final Serializable id = session.getId();
        final MongoDbSession dbSession = mongoDBSessionService.load(id.toString());
        if (dbSession != null) {
            final int deleted = mongoDBSessionService.destroy(dbSession);
            LOG.debug("Deleted {} sessions from database", deleted);
        } else {
            LOG.debug("Session not found in database");
        }
    }

