    public Collection<Session> getActiveSessions() {
        LOG.debug("Retrieving all active sessions.");

        Collection<MongoDbSession> dbSessions = mongoDBSessionService.loadAll();
        List<Session> sessions = Lists.newArrayList();
        for (MongoDbSession dbSession : dbSessions) {
            sessions.add(mongoDBSessionService.daoToSimpleSession(dbSession));
        }

        return sessions;
    }

private void terminateSessionsForUser(User user) {
        try {
            final Set<String> sessionIds = getSessionIDsForUser(user);

            for (final String sessionId : sessionIds) {
                getActiveSessionForID(sessionId).ifPresent(session -> {
                    LOG.info("Terminating session for user <{}/{}>", user.getName(), user.getId());
                    session.stop();
                });
            }
        } catch (Exception e) {
            LOG.error("Couldn't terminate session for user <{}/{}>", user.getName(), user.getId(), e);
        }
    }

