        if (token.startsWith("{") && token.endsWith("}")) {
            final int beginIndex = token.charAt(1) == '*' ? 2 : 1;
            return token.substring(beginIndex, token.length() - 1);
        }

        if (token.startsWith(":")) {
            final int beginIndex = token.charAt(1) == '*' ? 2 : 1;
            return token.substring(beginIndex);
        }

        return null;
