@Nullable
    private static RequestTarget parse(Mode mode, String rawPath) {
        switch (mode) {
            case SERVER:
                return forServer(rawPath);
            case CLIENT:
                return forClient(rawPath);
            default:
                throw new Error();
        }
    }

