			);
	}

public static int utf8DigitsToInt(byte[] buf, int begin, int end) {
		int val = 0;
		int mult = 1;

		for (int i = end - 1; i >= begin; i--) {
			val += ((int)buf[i] - 48) * mult;
			mult *= 10;
		}
		return val;
	}

