public void packMap(List<? extends Entry<?,?>> list, MapOrder order) {
		int attr = order.attributes;

		if (attr > 0) {
			// Map is sorted.
			packMapBegin(list.size() + 1);
			packByte(0xc7);
			packByte(0);
			packByte(attr);
			packByte(0xc0);
		}
		else {
			packMapBegin(list.size());
		}

		for (Entry<?,?> entry : list) {
			packObject(entry.getKey());
			packObject(entry.getValue());
		}
	}

public void packLong(long val) {
    	if (val >= 0L) {
        	if (val < 128L) {
        		packByte((int)val);
        		return;
        	}

        	if (val < 256L) {
        		packByte(0xcc, (int)val);
        		return;
        	}

        	if (val < 65536L) {
        		packShort(0xcd, (int)val);
        		return;
        	}

        	if (val < 4294967296L) {
        		packInt(0xce, (int)val);
        		return;
        	}
        	packLong(0xcf, val);
    	}
    	else {
        	if (val >= -32) {
        		packByte(0xe0 | ((int)val + 32));
        		return;
        	}

        	if (val >= Byte.MIN_VALUE) {
                packByte(0xd0, (int)val);
                return;
        	}

        	if (val >= Short.MIN_VALUE) {
                packShort(0xd1, (int)val);
                return;
        	}

        	if (val >= Integer.MIN_VALUE) {
        		packInt(0xd2, (int)val);
                return;
        	}
        	packLong(0xd3, val);
    	}
    }

