					Messages.ProjectSettingsExportStrategy_couldNotOpen);
			result = false;
		}

		URI uri = URIUtil.toURI(page.getDestinationFilePath());
		ResourcesUtil.refreshWorkspaceFiles(uri);

		return result;
	}

