public static IngestionSource mapIngestionSource(final EntityResponse ingestionSource) {
    final Urn entityUrn = ingestionSource.getUrn();
    final EnvelopedAspectMap aspects = ingestionSource.getAspects();

    // There should ALWAYS be an info aspect.
    final EnvelopedAspect envelopedInfo = aspects.get(Constants.INGESTION_INFO_ASPECT_NAME);

    if (envelopedInfo == null) {
      throw new IllegalStateException("No ingestion source info aspect exists for urn: " + entityUrn);
    }

    // Bind into a strongly typed object.
    final DataHubIngestionSourceInfo ingestionSourceInfo = new DataHubIngestionSourceInfo(envelopedInfo.getValue().data());

    return mapIngestionSourceInfo(entityUrn, ingestionSourceInfo);
  }

public static IngestionSource mapIngestionSourceInfo(final Urn urn, final DataHubIngestionSourceInfo info) {
    final IngestionSource result = new IngestionSource();
    result.setUrn(urn.toString());
    result.setName(info.getName());
    result.setType(info.getType());
    result.setConfig(mapIngestionSourceConfig(info.getConfig()));
    if (info.hasSchedule()) {
      result.setSchedule(mapIngestionSourceSchedule(info.getSchedule()));
    }
    return result;
  }

@Override
  public CompletableFuture<String> get(final DataFetchingEnvironment environment) throws Exception {
    final QueryContext context = environment.getContext();

    return CompletableFuture.supplyAsync(() -> {

      if (IngestionAuthUtils.canManageIngestion(context)) {

        final CreateIngestionExecutionRequestInput input =
            bindArgument(environment.getArgument("input"), CreateIngestionExecutionRequestInput.class);

        try {
          final ExecutionRequestKey key = new ExecutionRequestKey();
          final UUID uuid = UUID.randomUUID();
          final String uuidStr = uuid.toString();
          key.setId(uuidStr);
          final Urn executionRequestUrn = EntityKeyUtils.convertEntityKeyToUrn(key, EXECUTION_REQUEST_ENTITY_NAME);

          // Fetch the original ingestion source
          final Urn ingestionSourceUrn = Urn.createFromString(input.getIngestionSourceUrn());
          final Map<Urn, EntityResponse> response =
              _entityClient.batchGetV2(INGESTION_SOURCE_ENTITY_NAME, ImmutableSet.of(ingestionSourceUrn),
                  ImmutableSet.of(INGESTION_INFO_ASPECT_NAME), context.getAuthentication());

          if (!response.containsKey(ingestionSourceUrn)) {
            throw new DataHubGraphQLException(
                String.format("Failed to find ingestion source with urn %s", ingestionSourceUrn.toString()),
                DataHubGraphQLErrorCode.BAD_REQUEST);
          }

          final EnvelopedAspect envelopedInfo = response.get(ingestionSourceUrn).getAspects().get(INGESTION_INFO_ASPECT_NAME);
          final DataHubIngestionSourceInfo ingestionSourceInfo = new DataHubIngestionSourceInfo(envelopedInfo.getValue().data());

          if (!ingestionSourceInfo.getConfig().hasRecipe()) {
            throw new DataHubGraphQLException(
                String.format("Failed to find valid ingestion source with urn %s. Missing recipe", ingestionSourceUrn.toString()),
                DataHubGraphQLErrorCode.BAD_REQUEST);
          }

          // Build the arguments map.
          final ExecutionRequestInput execInput = new ExecutionRequestInput();
          execInput.setTask(RUN_INGEST_TASK_NAME); // Set the RUN_INGEST task
          execInput.setSource(
              new ExecutionRequestSource().setType(MANUAL_EXECUTION_SOURCE_NAME).setIngestionSource(ingestionSourceUrn));
          execInput.setExecutorId(ingestionSourceInfo.getConfig().getExecutorId(), SetMode.IGNORE_NULL);
          execInput.setRequestedAt(System.currentTimeMillis());

          Map<String, String> arguments = new HashMap<>();
          String recipe = ingestionSourceInfo.getConfig().getRecipe();
          recipe = injectRunId(recipe, executionRequestUrn.toString());
          recipe = IngestionUtils.injectPipelineName(recipe, ingestionSourceUrn.toString());
          arguments.put(RECIPE_ARG_NAME, recipe);
          arguments.put(VERSION_ARG_NAME, ingestionSourceInfo.getConfig().hasVersion()
              ? ingestionSourceInfo.getConfig().getVersion()
              : _ingestionConfiguration.getDefaultCliVersion()
          );
          if (ingestionSourceInfo.getConfig().hasVersion()) {
            arguments.put(VERSION_ARG_NAME, ingestionSourceInfo.getConfig().getVersion());
          }
          String debugMode = "false";
          if (ingestionSourceInfo.getConfig().hasDebugMode()) {
            debugMode = ingestionSourceInfo.getConfig().isDebugMode() ? "true" : "false";
          }
          arguments.put(DEBUG_MODE_ARG_NAME, debugMode);
          execInput.setArgs(new StringMap(arguments));

          final MetadataChangeProposal proposal = buildMetadataChangeProposalWithKey(key,
              EXECUTION_REQUEST_ENTITY_NAME, EXECUTION_REQUEST_INPUT_ASPECT_NAME, execInput);
          return _entityClient.ingestProposal(proposal, context.getAuthentication(), false);
        } catch (Exception e) {
          throw new RuntimeException(String.format("Failed to create new ingestion execution request %s", input), e);
        }
      }
      throw new AuthorizationException("Unauthorized to perform this action. Please contact your DataHub administrator.");
    });
  }

private String injectRunId(final String originalJson, final String runId) {
    try {
      JSONObject obj = new JSONObject(originalJson);
      obj.put("run_id", runId);
      return obj.toString();
    } catch (JSONException e) {
      // This should ideally never be hit.
      throw new IllegalArgumentException("Failed to create execution request: Invalid recipe json provided.");
    }
  }

