@Override
    public String fieldPathType() {
        return Optional.ofNullable(fieldPathType).orElseGet(() -> {
            final String pathType;

            switch (fieldProto.getType()) {
                case TYPE_DOUBLE:
                    pathType = "double";
                    break;
                case TYPE_FLOAT:
                    pathType = "float";
                    break;
                case TYPE_SFIXED64:
                case TYPE_FIXED64:
                case TYPE_UINT64:
                case TYPE_INT64:
                case TYPE_SINT64:
                    pathType = "long";
                    break;
                case TYPE_FIXED32:
                case TYPE_SFIXED32:
                case TYPE_INT32:
                case TYPE_UINT32:
                case TYPE_SINT32:
                    pathType = "int";
                    break;
                case TYPE_BYTES:
                    pathType = "bytes";
                    break;
                case TYPE_ENUM:
                    pathType = "enum";
                    break;
                case TYPE_BOOL:
                    pathType = "boolean";
                    break;
                case TYPE_STRING:
                    pathType = "string";
                    break;
                case TYPE_GROUP:
                case TYPE_MESSAGE:
                    pathType = nativeType().replace(".", "_");
                    break;
                default:
                    throw new IllegalStateException(String.format("Unexpected FieldDescriptorProto => FieldPathType %s", fieldProto.getType()));
            }

            StringArray fieldPath = new StringArray();

            if (schemaFieldDataType().getType().isArrayType()) {
                fieldPath.add("[type=array]");
            }

            fieldPath.add(String.format("[type=%s]", pathType));

            return String.join(".", fieldPath);
        });
    }

