                if (encodingState != null && encodingState.getEncoders() != null && encodingState.getEncoders().size() > 0) {
                    Encoder encoder=encodingState.getEncoders().iterator().next();
                    if (encoder != null)
                        encoder.markEncoded(stringChunk.str);
                }
            }
        }
    }

