        TaskManager.taskManager().sync(() -> {
            InventoryHolder chest = (InventoryHolder) state;
            Inventory inven = chest.getInventory();
            if (chest instanceof Chest) {
                inven = ((Chest) chest).getBlockInventory();
            }
            inven.clear();
            return null;
        });
        return true;
    }

